\[\frac{BD}{AB} = \frac{CD}{AC},\]or $\frac{BD}{6} = \frac{AC}{3},$ so $BD = 2CD.$  Let $x = CD$; then $BD = 2x.$

[asy]
unitsize (0.8 cm);

pair A, B, C, D;

B = (0,0);
C = (3*sqrt(7),0);
A = intersectionpoint(arc(B,6,0,180),arc(C,3,0,180));
D = interp(B,C,2/3);

draw(A--B--C--cycle);
draw(A--D);

label("$A$", A, N);
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, S);
label("$3$", (A + C)/2, NE);
label("$6$", (A + B)/2, NW);
label("$x$", (C + D)/2, S);
label("$2x$", (B + D)/2, S);
label("$d$", (A + D)/2, W);
[/asy]

